-- =====================================================================
-- CivicScope Light : données de référence pour le module FRWE518
-- Présidentielles sénégalaises 2019 et 2024, du bureau de vote au national.
-- Version allégée du dump CivicScope : sans PostGIS, candidats en une seule table,
-- noms de colonnes alignés sur les entités JPA du cours.
--
-- Import (en tant qu'utilisateur civicscope, dans la base civicscope) :
--   psql -U civicscope -d civicscope -h localhost -f civicscope_data.sql
-- ou dans pgAdmin : Query Tool sur la base civicscope, ouvrir le fichier, exécuter.
-- Le script est rejouable : il supprime puis recrée ses tables.
-- =====================================================================

BEGIN;

DROP TABLE IF EXISTS resultat_candidat, resultat_election, election_candidats, candidat,
    election, bureau_vote, centre_vote, commune, departement, region CASCADE;

CREATE TABLE region (
    id   uuid PRIMARY KEY,
    code varchar(20)  NOT NULL UNIQUE,
    nom  varchar(255) NOT NULL
);

CREATE TABLE departement (
    id        uuid PRIMARY KEY,
    code      varchar(20)  NOT NULL UNIQUE,
    nom       varchar(255) NOT NULL,
    region_id uuid NOT NULL REFERENCES region (id)
);

CREATE TABLE commune (
    id             uuid PRIMARY KEY,
    code           varchar(20)  NOT NULL UNIQUE,
    nom            varchar(255) NOT NULL,
    code_postal    varchar(20),
    departement_id uuid NOT NULL REFERENCES departement (id)
);

CREATE TABLE centre_vote (
    id         uuid PRIMARY KEY,
    code       varchar(100) NOT NULL UNIQUE,
    nom        varchar(255) NOT NULL,
    commune_id uuid NOT NULL REFERENCES commune (id)
);

CREATE TABLE bureau_vote (
    id             uuid PRIMARY KEY,
    code           varchar(100) NOT NULL UNIQUE,
    nom            varchar(255) NOT NULL,
    centre_vote_id uuid NOT NULL REFERENCES centre_vote (id)
);

CREATE TABLE election (
    id            uuid PRIMARY KEY,
    code          varchar(50) NOT NULL UNIQUE,
    date          date        NOT NULL,
    type_election varchar(50) NOT NULL,
    tour_election varchar(50),
    code_pays     varchar(10)
);

CREATE TABLE candidat (
    id              uuid PRIMARY KEY,
    prenom          varchar(255),
    nom             varchar(255) NOT NULL,
    genre           varchar(20),
    parti_politique varchar(255),
    couleur         varchar(20)
);

CREATE TABLE election_candidats (
    election_id uuid NOT NULL REFERENCES election (id),
    candidat_id uuid NOT NULL REFERENCES candidat (id),
    PRIMARY KEY (election_id, candidat_id)
);

CREATE TABLE resultat_election (
    id                             uuid PRIMARY KEY,
    bureau_vote_id                 uuid NOT NULL REFERENCES bureau_vote (id),
    election_id                    uuid NOT NULL REFERENCES election (id),
    nombre_inscrits                integer,
    nombre_votants                 integer,
    bulletins_nuls                 integer,
    bulletins_blancs               integer,
    suffrages_valablement_exprimes integer,
    UNIQUE (bureau_vote_id, election_id)
);

CREATE TABLE resultat_candidat (
    id                   uuid PRIMARY KEY,
    resultat_election_id uuid NOT NULL REFERENCES resultat_election (id),
    candidat_id          uuid NOT NULL REFERENCES candidat (id),
    nombre_voix          integer,
    UNIQUE (resultat_election_id, candidat_id)
);

-- region : 14 lignes

-- departement : 45 lignes

-- commune : 552 lignes

-- centre_vote : 2756 lignes

-- bureau_vote : 3316 lignes

-- election : 2 lignes

-- candidat : 9 lignes

-- election_candidats : 10 lignes

-- resultat_election : 6632 lignes

-- resultat_candidat : 33160 lignes

COMMIT;
